# -- helper: integer mode with tie -&gt; smallest
mode_pick_int &lt;- function(x){
  x &lt;- x[!is.na(x)]
  if(length(x)==0) return(NA_integer_)
  tx &lt;- sort(table(x), decreasing = TRUE)
  as.integer(names(tx)[1L])
}

# 1) Build a STRICT one-row-per-hash ANY table -------------------------
