project_root &lt;- tryCatch({
  if (grepl("/cons$", cwd)) {
    dirname(cwd)

  } else if (grepl("\\\\cons$", cwd)) {
    dirname(cwd)
  } else if (file.exists(file.path(cwd, "cons"))) {
    cwd
  } else {
    # Search recursively
    candidate &lt;- list.files(
      cwd,
      pattern = "pred2._ndp_.*\\.Rdata$",
      recursive = TRUE,
      full.names = TRUE
    )
    if (length(candidate) &gt; 0) {
      dirname(dirname(candidate[1]))
    } else {
      cwd
    }
  }
}, error = function(e) cwd)

